 private static List<Account> accounts(Integer n){List<Account> rows=new List<Account>();for(Integer i=0;i<n;i++)rows.add(new Account(Name='V05_'+String.valueOf(i).leftPad(5,'0'),Phone='ORIGINAL'));return rows;}
